/**
 * PluresDB NAPI backend — uses the native Rust bindings directly.
 *
 * Initialises PluresDB with `PluresDatabase.newWithEmbeddings("BAAI/bge-small-en-v1.5")`
 * so that all stored text is automatically embedded by PluresDB's built-in
 * FastEmbedder (fastembed/ONNX Runtime).  pluresLM no longer needs a
 * client-side embedding pipeline for write operations.
 *
 * For read/recall operations (vectorSearch, dedup checks) the caller still
 * provides a pre-computed query embedding — typically generated by the
 * configured Ollama endpoint using the same BAAI/bge-small-en-v1.5 model so
 * that vector dimensions are consistent (384-d).
 *
 * Requires: @plures/pluresdb compiled with --features embeddings
 */

import { randomUUID } from "node:crypto";
import { createRequire } from "node:module";
import * as path from "node:path";
import * as fs from "node:fs";
import type {
  MemoryEntry,
  MemorySearchResult,
  ProfileData,
  DailySummary,
  MemoryPriority,
  ConversationTag,
} from "./memory-db.js";
import { determinePriority } from "./memory-db.js";

// ── Key prefixes (must match PluresDBBackend for data compatibility) ──────────
const MEM = "memory:";
const EDGE = "edge:";
const PROFILE_KEY = "profile:user_profile";
const SYNC = "sync:";
const CONV_TAG = "conv_tag:";

// ── NAPI type shims ────────────────────────────────────────────────────────────
// Defined here so we don't introduce a hard dependency on @plures/pluresdb.
// The actual implementation is loaded at runtime via createRequire.
interface VectorSearchItem {
  id: string;
  data: unknown;
  score: number;
  timestamp: string;
}

interface NativePluresDatabase {
  put(id: string, data: unknown): string;
  putWithEmbedding(id: string, data: unknown, embedding: number[]): string;
  get(id: string): unknown | null;
  getWithMetadata(id: string): unknown | null;
  delete(id: string): void;
  list(): unknown[];
  listByType(nodeType: string): unknown[];
  search(query: string, limit?: number | null): unknown[];
  vectorSearch(
    embedding: number[],
    limit?: number | null,
    threshold?: number | null,
  ): VectorSearchItem[];
  getActorId(): string;
  stats(): unknown;
}

interface NativePluresDatabaseConstructor {
  new (actorId?: string | null, dbPath?: string | null): NativePluresDatabase;
  newWithEmbeddings(
    model: string,
    actorId?: string | null,
  ): NativePluresDatabase;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function cosineSimilarity(a: number[], b: number[]): number {
  const len = Math.min(a.length, b.length);
  if (len === 0) return 0;
  let dot = 0,
    normA = 0,
    normB = 0;
  for (let i = 0; i < len; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  return denom === 0 ? 0 : dot / denom;
}

function toNumberArray(v: unknown): number[] {
  if (!Array.isArray(v)) return [];
  return (v as unknown[]).filter(
    (x): x is number => typeof x === "number",
  );
}

interface NapiListItem {
  id: string;
  data: Record<string, unknown>;
}

function toListItem(raw: unknown): NapiListItem | null {
  if (!raw || typeof raw !== "object") return null;
  const obj = raw as Record<string, unknown>;
  if (typeof obj.id !== "string") return null;
  const data =
    obj.data && typeof obj.data === "object"
      ? (obj.data as Record<string, unknown>)
      : {};
  return { id: obj.id, data };
}

// ── PluresNapiBackend ─────────────────────────────────────────────────────────

export class PluresNapiBackend {
  private db: NativePluresDatabase | null = null;
  private closed = false;
  private readonly dbPath: string;
  private readonly model: string;
  private readonly actorId: string | undefined;

  /** PluresDB auto-embedding model used for stored text. */
  static readonly EMBEDDING_MODEL = "BAAI/bge-small-en-v1.5";
  /** Embedding dimension produced by BAAI/bge-small-en-v1.5. */
  static readonly EMBEDDING_DIM = 384;

  constructor(
    dbPath: string,
    _vectorDimension: number,
    actorId?: string,
  ) {
    this.dbPath = dbPath;
    this.model = PluresNapiBackend.EMBEDDING_MODEL;
    this.actorId = actorId;
  }

  // ── Lifecycle ─────────────────────────────────────────────────────────────

  private ensureOpen(): NativePluresDatabase {
    if (this.closed || !this.db) {
      throw new Error("PluresNapiBackend is not open");
    }
    return this.db;
  }

  /** Load and initialise the NAPI module with auto-embedding enabled. */
  async open(): Promise<void> {
    if (this.db) return;

    const require = createRequire(import.meta.url);

    // Resolve the NAPI entry point (dist/napi/index.js)
    let napiIndexPath: string;
    try {
      napiIndexPath = require.resolve("@plures/pluresdb");
    } catch {
      throw new Error(
        "@plures/pluresdb is not installed. Run: npm install @plures/pluresdb",
      );
    }

    // Check that the native binary loader exists
    const nativeLoaderPath = path.join(
      path.dirname(napiIndexPath),
      "../../crates/pluresdb-node/index.js",
    );
    if (!fs.existsSync(nativeLoaderPath)) {
      throw new Error(
        `PluresDB native binary loader not found at ${nativeLoaderPath}. ` +
          "Ensure @plures/pluresdb is installed with native binaries.",
      );
    }

    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const mod = require(napiIndexPath) as Record<string, unknown>;

    // Support both { PluresDatabase } and { default: { PluresDatabase } } exports.
    const modDefault = (mod.default ?? {}) as Record<string, unknown>;
    const PluresDatabase = (mod.PluresDatabase ?? modDefault.PluresDatabase) as
      | NativePluresDatabaseConstructor
      | undefined;
    if (!PluresDatabase) {
      throw new Error("PluresDatabase not found in @plures/pluresdb module");
    }

    this.db = PluresDatabase.newWithEmbeddings(
      this.model,
      this.actorId ?? null,
    );

    this.closed = false;
  }

  async close(): Promise<void> {
    this.closed = true;
    this.db = null;
  }

  async reopen(): Promise<void> {
    await this.close();
    this.closed = false;
    await this.open();
  }

  async isOpen(): Promise<boolean> {
    return !this.closed && this.db !== null;
  }

  // ── NAPI primitives ───────────────────────────────────────────────────────

  private napiPut(id: string, data: Record<string, unknown>): void {
    // NAPI put() auto-embeds text content fields (content, text) via FastEmbedder.
    this.ensureOpen().put(id, data);
  }

  private napiGet(id: string): Record<string, unknown> | null {
    const raw = this.ensureOpen().get(id);
    if (!raw || typeof raw !== "object") return null;
    // NAPI get() returns the stored data directly
    return raw as Record<string, unknown>;
  }

  private napiDelete(id: string): void {
    this.ensureOpen().delete(id);
  }

  private napiList(): NapiListItem[] {
    const raw = this.ensureOpen().list();
    const items: NapiListItem[] = [];
    for (const r of raw) {
      const item = toListItem(r);
      if (item) items.push(item);
    }
    return items;
  }

  private napiVectorSearch(
    embedding: number[],
    limit: number,
    threshold: number,
  ): VectorSearchItem[] {
    return this.ensureOpen().vectorSearch(embedding, limit, threshold);
  }

  // ── IMemoryBackend implementation ─────────────────────────────────────────

  async store(
    content: string,
    embedding: number[],
    opts: {
      source?: string;
      tags?: string[];
      category?: string;
      priority?: MemoryPriority;
      dedupeThreshold?: number;
      importanceScore?: number;
      originator_id?: string;
      originator_name?: string;
      destination?: string;
      status?: string;
      assigned_to?: string;
      due_at?: number;
      last_checkin?: number;
    },
  ): Promise<{ entry: MemoryEntry; isDuplicate: boolean; updatedId?: string }> {
    this.ensureOpen();

    const tags = opts.tags ?? [];
    const category = opts.category ?? "other";
    const priority = opts.priority ?? determinePriority(category, tags);
    const importanceScore = opts.importanceScore ?? 1.0;
    const threshold = opts.dedupeThreshold ?? 0.95;

    // Dedup: use query embedding (caller-provided) to find near-duplicates.
    // The stored embedding was generated by PluresDB's FastEmbedder on the
    // previous put(); we compare against it using the caller's query vector.
    if (embedding.length > 0) {
      const dupeResults = await this.vectorSearch(embedding, 1, threshold);
      if (dupeResults.length > 0) {
        const ex = dupeResults[0].entry;
        const now = Date.now();
        const mergedTags = opts.tags ?? ex.tags ?? [];
        const mergedCategory = opts.category ?? ex.category ?? "other";
        const mergedImportanceScore =
          opts.importanceScore ?? ex.importance_score ?? 1.0;
        const mergedSource = opts.source ?? ex.source ?? "";
        const mergedPriority =
          opts.priority ?? determinePriority(mergedCategory, mergedTags);

        const updated: MemoryEntry = {
          ...ex,
          content,
          embedding,
          created_at: now,
          source: mergedSource,
          tags: mergedTags,
          category: mergedCategory,
          importance_score: mergedImportanceScore,
          priority: mergedPriority,
        };
        // Re-store: NAPI will re-embed the updated content automatically.
        this.napiPut(MEM + ex.id, this.entryToNode(updated));
        return { entry: updated, isDuplicate: true, updatedId: ex.id };
      }
    }

    const id = randomUUID();
    const now = Date.now();

    // Assign conversation tag using caller-provided embedding (for similarity).
    const conversationTagIds =
      embedding.length > 0
        ? await this.assignConversationTag(id, embedding, content)
        : [];

    const entry: MemoryEntry = {
      id,
      content,
      embedding,
      created_at: now,
      source: opts.source ?? "",
      tags,
      category,
      priority,
      importance_score: importanceScore,
      conversation_tag_ids: conversationTagIds,
      originator_id: opts.originator_id || undefined,
      originator_name: opts.originator_name || undefined,
      destination: opts.destination || undefined,
      status: opts.status || undefined,
      assigned_to: opts.assigned_to || undefined,
      due_at: opts.due_at,
      last_checkin: opts.last_checkin,
    };

    // NAPI put() auto-embeds `content` via FastEmbedder (BAAI/bge-small-en-v1.5).
    // We do NOT include the `vector` field so NAPI can manage the embedding.
    this.napiPut(MEM + id, this.entryToNode(entry));
    return { entry, isDuplicate: false };
  }

  async vectorSearch(
    queryEmbedding: number[],
    limit: number = 5,
    minScore: number = 0.3,
  ): Promise<MemorySearchResult[]> {
    this.ensureOpen();

    const candidates = this.napiVectorSearch(
      queryEmbedding,
      limit * 3 + 10,
      0.0,
    );

    const results: MemorySearchResult[] = [];
    for (const item of candidates) {
      if (!item.id.startsWith(MEM)) continue;
      const d =
        item.data && typeof item.data === "object"
          ? (item.data as Record<string, unknown>)
          : {};
      const importanceScore =
        typeof d.importance_score === "number" ? d.importance_score : 1.0;
      const finalScore = item.score * importanceScore;
      if (finalScore < minScore) continue;

      results.push({
        entry: this.nodeToEntry(d, item.id.slice(MEM.length)),
        score: finalScore,
      });
    }

    return results
      .sort((a, b) => b.score - a.score)
      .slice(0, limit);
  }

  async vectorSearchBoosted(
    queryEmbedding: number[],
    limit: number = 5,
    minScore: number = 0.3,
    boostCategories: Record<string, number> = {},
  ): Promise<MemorySearchResult[]> {
    const base = await this.vectorSearch(queryEmbedding, limit * 2, minScore / 2);
    const now = Date.now();

    const boosted = base.map((r) => {
      const categoryBoost = boostCategories[r.entry.category] ?? 1.0;
      const ageMs = now - r.entry.created_at;
      const ageDays = ageMs / (24 * 60 * 60 * 1000);
      const ageFactor = Math.exp(-ageDays / 30);
      return { ...r, score: r.score * categoryBoost * (0.7 + 0.3 * ageFactor) };
    });

    return boosted
      .filter((r) => r.score >= minScore)
      .sort((a, b) => b.score - a.score)
      .slice(0, limit);
  }

  async addEdge(
    fromId: string,
    toId: string,
    relation: string,
  ): Promise<void> {
    this.ensureOpen();
    const edgeId = `${fromId}-${relation}-${toId}`;
    this.napiPut(EDGE + edgeId, {
      from_id: fromId,
      to_id: toId,
      relation,
      created_at: Date.now(),
    });
  }

  async getRelated(
    memoryId: string,
    relation?: string,
  ): Promise<MemoryEntry[]> {
    this.ensureOpen();
    const all = this.napiList();
    const entries: MemoryEntry[] = [];

    for (const node of all) {
      if (!node.id.startsWith(EDGE)) continue;
      const d = node.data;
      if (d.from_id !== memoryId) continue;
      if (relation && d.relation !== relation) continue;

      const toId = d.to_id as string;
      const data = this.napiGet(MEM + toId);
      if (data) entries.push(this.nodeToEntry(data, toId));
    }

    return entries;
  }

  async delete(id: string): Promise<boolean> {
    this.ensureOpen();
    const existing = this.napiGet(MEM + id);
    if (!existing) return false;
    this.napiDelete(MEM + id);
    return true;
  }

  async deleteBySource(source: string): Promise<number> {
    this.ensureOpen();
    const all = this.napiList();
    let count = 0;
    for (const node of all) {
      if (!node.id.startsWith(MEM)) continue;
      if (node.data.source === source) {
        this.napiDelete(node.id);
        count++;
      }
    }
    return count;
  }

  async deleteByQuery(
    embedding: number[],
    threshold: number = 0.8,
  ): Promise<number> {
    const matches = await this.vectorSearch(embedding, 10, threshold);
    for (const m of matches) {
      this.napiDelete(MEM + m.entry.id);
    }
    return matches.length;
  }

  async count(): Promise<number> {
    this.ensureOpen();
    return this.napiList().filter((n) => n.id.startsWith(MEM)).length;
  }

  async getAllContent(limit: number = 100): Promise<string[]> {
    this.ensureOpen();
    return this.napiList()
      .filter((n) => n.id.startsWith(MEM))
      .slice(0, limit)
      .map((n) => (n.data.content as string) ?? "");
  }

  async getLastCaptureTime(): Promise<number | null> {
    this.ensureOpen();
    const all = this.napiList().filter((n) => n.id.startsWith(MEM));
    if (all.length === 0) return null;
    return Math.max(...all.map((n) => (n.data.created_at as number) ?? 0));
  }

  async getProfile(): Promise<ProfileData | null> {
    this.ensureOpen();
    const raw = this.napiGet(PROFILE_KEY);
    if (!raw) return null;
    return raw as unknown as ProfileData;
  }

  async setProfile(profile: ProfileData): Promise<void> {
    this.ensureOpen();
    this.napiPut(PROFILE_KEY, profile as unknown as Record<string, unknown>);
  }

  async incrementCaptureCount(): Promise<number> {
    this.ensureOpen();
    const raw = this.napiGet(PROFILE_KEY);
    const profile = (raw ?? {}) as Record<string, unknown>;
    const count = ((profile.capture_count as number) ?? 0) + 1;
    this.napiPut(PROFILE_KEY, { ...profile, capture_count: count });
    return count;
  }

  async stats(): Promise<{
    totalMemories: number;
    categories: Record<string, number>;
    edgeCount: number;
    lastCaptureTime: number | null;
  }> {
    this.ensureOpen();
    const all = this.napiList();
    const memories = all.filter((n) => n.id.startsWith(MEM));
    const edges = all.filter((n) => n.id.startsWith(EDGE));

    const categories: Record<string, number> = {};
    let lastCaptureTime: number | null = null;

    for (const n of memories) {
      const cat = (n.data.category as string) ?? "other";
      categories[cat] = (categories[cat] ?? 0) + 1;
      const ts = n.data.created_at as number;
      if (ts && (!lastCaptureTime || ts > lastCaptureTime)) {
        lastCaptureTime = ts;
      }
    }

    return {
      totalMemories: memories.length,
      categories,
      edgeCount: edges.length,
      lastCaptureTime,
    };
  }

  async getMemoriesByCategories(
    categories: string[],
    limit: number,
    recencyBias: number,
  ): Promise<MemoryEntry[]> {
    this.ensureOpen();
    const all = this.napiList();
    const now = Date.now();

    const candidates = all
      .filter(
        (n) =>
          n.id.startsWith(MEM) &&
          (n.data.category as string) !== "daily-summary" &&
          categories.includes((n.data.category as string) ?? "other"),
      )
      .map((n) => {
        const ts = (n.data.created_at as number) ?? 0;
        const ageDays = (now - ts) / (24 * 60 * 60 * 1000);
        const recencyScore = Math.exp(-ageDays * recencyBias * 0.1);
        const importanceScore =
          typeof n.data.importance_score === "number"
            ? n.data.importance_score
            : 1.0;
        return { node: n, score: recencyScore * importanceScore };
      })
      .sort((a, b) => b.score - a.score)
      .slice(0, limit);

    return candidates.map((c) =>
      this.nodeToEntry(c.node.data, c.node.id.slice(MEM.length)),
    );
  }

  async getMemoriesSince(
    timestamp: number,
  ): Promise<Array<Omit<MemoryEntry, "embedding">>> {
    this.ensureOpen();
    return this.napiList()
      .filter(
        (n) =>
          n.id.startsWith(MEM) &&
          ((n.data.created_at as number) ?? 0) >= timestamp,
      )
      .map((n) =>
        this.nodeToEntryNoEmbedding(n.data, n.id.slice(MEM.length)),
      );
  }

  async getAllMemoryIds(): Promise<Array<{ id: string; created_at: number }>> {
    this.ensureOpen();
    return this.napiList()
      .filter((n) => n.id.startsWith(MEM))
      .map((n) => ({
        id: n.id.slice(MEM.length),
        created_at: (n.data.created_at as number) ?? 0,
      }));
  }

  async getMemoriesByIds(
    ids: string[],
  ): Promise<Array<Omit<MemoryEntry, "embedding">>> {
    this.ensureOpen();
    const set = new Set(ids);
    return this.napiList()
      .filter((n) => n.id.startsWith(MEM) && set.has(n.id.slice(MEM.length)))
      .map((n) =>
        this.nodeToEntryNoEmbedding(n.data, n.id.slice(MEM.length)),
      );
  }

  async storeRaw(entry: Omit<MemoryEntry, "embedding">): Promise<boolean> {
    this.ensureOpen();
    try {
      // No embedding in storeRaw — NAPI will auto-embed content.
      this.napiPut(MEM + entry.id, {
        id: entry.id,
        content: entry.content,
        created_at: entry.created_at,
        source: entry.source ?? "",
        tags: entry.tags ?? [],
        category: entry.category ?? "other",
        priority: entry.priority ?? "normal",
        importance_score: entry.importance_score ?? 1.0,
        conversation_tag_ids: [],
        originator_id: entry.originator_id ?? "",
        originator_name: entry.originator_name ?? "",
        destination: entry.destination ?? "",
        status: entry.status ?? "",
        assigned_to: entry.assigned_to ?? "",
        ...(entry.due_at !== undefined ? { due_at: entry.due_at } : {}),
        ...(entry.last_checkin !== undefined
          ? { last_checkin: entry.last_checkin }
          : {}),
      });
      return true;
    } catch {
      return false;
    }
  }

  async setEmbedding(id: string, embedding: number[]): Promise<void> {
    this.ensureOpen();
    const existing = this.napiGet(MEM + id);
    if (!existing) return;
    // Use putWithEmbedding to store an explicit embedding alongside the node.
    this.ensureOpen().putWithEmbedding(
      MEM + id,
      existing,
      embedding,
    );
  }

  async getLastSyncTime(peerId: string): Promise<number> {
    this.ensureOpen();
    const raw = this.napiGet(SYNC + peerId);
    if (!raw) return 0;
    return (raw.timestamp as number) ?? 0;
  }

  async setLastSyncTime(peerId: string, timestamp: number): Promise<void> {
    this.ensureOpen();
    this.napiPut(SYNC + peerId, { peerId, timestamp });
  }

  async updateAttribution(
    id: string,
    opts: {
      status?: string;
      assigned_to?: string;
      due_at?: number | null;
      last_checkin?: number | null;
      destination?: string;
    },
  ): Promise<boolean> {
    this.ensureOpen();
    const existing = this.napiGet(MEM + id);
    if (!existing) return false;

    const updated = { ...existing };
    if (opts.status !== undefined) updated.status = opts.status;
    if (opts.assigned_to !== undefined) updated.assigned_to = opts.assigned_to;
    if (opts.destination !== undefined) updated.destination = opts.destination;
    if (opts.due_at !== undefined)
      updated.due_at = opts.due_at ?? undefined;
    if (opts.last_checkin !== undefined)
      updated.last_checkin = opts.last_checkin ?? undefined;

    this.napiPut(MEM + id, updated);
    return true;
  }

  async generateDailySummary(date: string): Promise<DailySummary> {
    this.ensureOpen();

    const dateObj = new Date(date + "T00:00:00.000Z");
    const startOfDay = dateObj.getTime();
    const endOfDay = startOfDay + 24 * 60 * 60 * 1000;

    const all = this.napiList();
    const memories = all
      .filter(
        (n) =>
          n.id.startsWith(MEM) &&
          (n.data.category as string) !== "daily-summary" &&
          (n.data.created_at as number) >= startOfDay &&
          (n.data.created_at as number) < endOfDay,
      )
      .sort(
        (a, b) =>
          (a.data.created_at as number) - (b.data.created_at as number),
      )
      .map((n) => ({
        id: n.id.slice(MEM.length),
        content: n.data.content as string,
        created_at: n.data.created_at as number,
        category: (n.data.category as string) ?? "other",
        tags: (n.data.tags as string[]) ?? [],
      }));

    const categorizedMemories = new Map<
      string,
      Array<{ content: string; created_at: number }>
    >();
    const categoryCounts: Record<string, number> = {};

    for (const mem of memories) {
      if (!categorizedMemories.has(mem.category)) {
        categorizedMemories.set(mem.category, []);
      }
      categorizedMemories
        .get(mem.category)!
        .push({ content: mem.content, created_at: mem.created_at });
      categoryCounts[mem.category] =
        (categoryCounts[mem.category] || 0) + 1;
    }

    const sections: string[] = [];
    sections.push(
      `# Daily Summary - ${date}`,
      "",
      `**Total Memories**: ${memories.length}`,
      "",
    );

    const categoryOrder = [
      "decision",
      "project",
      "work-in-progress",
      "architecture-decision",
      "error-fix",
      "code-pattern",
      "preference",
      "explicit",
      "entity",
      "conversation",
      "other",
    ];
    const sortedCategories = Array.from(categorizedMemories.keys()).sort(
      (a, b) => {
        const ia = categoryOrder.indexOf(a),
          ib = categoryOrder.indexOf(b);
        if (ia === -1 && ib === -1) return a.localeCompare(b);
        if (ia === -1) return 1;
        if (ib === -1) return -1;
        return ia - ib;
      },
    );

    for (const category of sortedCategories) {
      const items = categorizedMemories.get(category)!;
      const title = category
        .split("-")
        .map((w) => w.charAt(0).toUpperCase() + w.slice(1))
        .join(" ");
      sections.push(`## ${title} (${items.length})`, "");
      for (const item of items) {
        const time = new Date(item.created_at).toLocaleTimeString("en-US", {
          hour: "2-digit",
          minute: "2-digit",
          hour12: false,
        });
        sections.push(`- **${time}**: ${item.content}`);
      }
      sections.push("");
    }

    const summaryMarkdown = sections.join("\n");
    const now = Date.now();
    const summaryId = `daily-summary:${date}`;

    this.napiPut(MEM + summaryId, {
      id: summaryId,
      content: summaryMarkdown,
      created_at: now,
      source: "daily-summary",
      tags: [`daily-summary:${date}`],
      category: "daily-summary",
    });

    return {
      date,
      summary: summaryMarkdown,
      memoryCount: memories.length,
      categories: categoryCounts,
      created_at: now,
    };
  }

  async getDailySummaries(days: number): Promise<DailySummary[]> {
    this.ensureOpen();
    const startTime = Date.now() - days * 24 * 60 * 60 * 1000;

    return this.napiList()
      .filter(
        (n) =>
          n.id.startsWith(MEM) &&
          (n.data.category as string) === "daily-summary" &&
          ((n.data.created_at as number) ?? 0) >= startTime,
      )
      .sort(
        (a, b) =>
          (b.data.created_at as number) - (a.data.created_at as number),
      )
      .map((n) => {
        const tags = (n.data.tags as string[]) ?? [];
        const dateTag = tags.find((t) => t.startsWith("daily-summary:"));
        const date = dateTag
          ? dateTag.substring("daily-summary:".length)
          : "unknown";
        const content = n.data.content as string;
        const categories: Record<string, number> = {};
        let totalCount = 0;
        for (const match of content.matchAll(
          /^## (.+?) \((\d+)\)$/gm,
        )) {
          const categoryName = match[1].toLowerCase().replace(/\s+/g, "-");
          const count = parseInt(match[2], 10);
          categories[categoryName] = count;
          totalCount += count;
        }
        return {
          date,
          summary: content,
          memoryCount: totalCount,
          categories,
          created_at: n.data.created_at as number,
        };
      });
  }

  async getEmbeddingByteLength(): Promise<number | null> {
    this.ensureOpen();
    const all = this.napiList();
    for (const n of all) {
      if (!n.id.startsWith(MEM)) continue;
      // For NAPI auto-embedding, the stored vector is 384-dim f32 values
      // but not directly accessible via list().  Report the expected size.
      if (n.data.content) {
        // Return expected byte length: 384 dims × 8 bytes (Float64Array compat)
        return PluresNapiBackend.EMBEDDING_DIM * 8;
      }
    }
    return null;
  }

  // ── Private helpers ────────────────────────────────────────────────────────

  /**
   * Convert a MemoryEntry to a plain object for NAPI storage.
   * NOTE: the `vector` field is intentionally omitted — NAPI auto-embeds
   * the `content` field via FastEmbedder when using newWithEmbeddings().
   */
  private entryToNode(entry: MemoryEntry): Record<string, unknown> {
    return {
      id: entry.id,
      content: entry.content,
      // No `vector` field — PluresDB auto-embeds via FastEmbedder
      created_at: entry.created_at,
      source: entry.source ?? "",
      tags: entry.tags ?? [],
      category: entry.category ?? "other",
      priority: entry.priority ?? "normal",
      importance_score: entry.importance_score ?? 1.0,
      conversation_tag_ids: entry.conversation_tag_ids ?? [],
      originator_id: entry.originator_id ?? "",
      originator_name: entry.originator_name ?? "",
      destination: entry.destination ?? "",
      status: entry.status ?? "",
      assigned_to: entry.assigned_to ?? "",
      ...(entry.last_accessed_at !== undefined
        ? { last_accessed_at: entry.last_accessed_at }
        : {}),
      ...(entry.merge_count !== undefined
        ? { merge_count: entry.merge_count }
        : {}),
      ...(entry.due_at !== undefined ? { due_at: entry.due_at } : {}),
      ...(entry.last_checkin !== undefined
        ? { last_checkin: entry.last_checkin }
        : {}),
    };
  }

  /** Reconstruct a MemoryEntry from NAPI node data. */
  private nodeToEntry(
    data: Record<string, unknown>,
    id: string,
  ): MemoryEntry {
    return {
      id,
      content: (data.content as string) ?? "",
      // Embedding is managed by PluresDB; expose an empty array for callers
      // that don't need it (vectorSearch callers get the score instead).
      embedding: toNumberArray(data.vector),
      created_at: (data.created_at as number) ?? 0,
      source: (data.source as string) ?? "",
      tags: (data.tags as string[]) ?? [],
      category: (data.category as string) ?? "other",
      priority: (data.priority as MemoryPriority) ?? "normal",
      importance_score:
        typeof data.importance_score === "number"
          ? data.importance_score
          : 1.0,
      conversation_tag_ids: Array.isArray(data.conversation_tag_ids)
        ? (data.conversation_tag_ids as string[])
        : [],
      originator_id: (data.originator_id as string) || undefined,
      originator_name: (data.originator_name as string) || undefined,
      destination: (data.destination as string) || undefined,
      status: (data.status as string) || undefined,
      assigned_to: (data.assigned_to as string) || undefined,
      due_at:
        typeof data.due_at === "number" ? data.due_at : undefined,
      last_checkin:
        typeof data.last_checkin === "number" ? data.last_checkin : undefined,
      ...(data.last_accessed_at !== undefined
        ? { last_accessed_at: data.last_accessed_at as number }
        : {}),
      ...(data.merge_count !== undefined
        ? { merge_count: data.merge_count as number }
        : {}),
    };
  }

  private nodeToEntryNoEmbedding(
    data: Record<string, unknown>,
    id: string,
  ): Omit<MemoryEntry, "embedding"> {
    return {
      id,
      content: (data.content as string) ?? "",
      created_at: (data.created_at as number) ?? 0,
      source: (data.source as string) ?? "",
      tags: (data.tags as string[]) ?? [],
      category: (data.category as string) ?? "other",
      priority: (data.priority as MemoryPriority) ?? "normal",
      importance_score:
        typeof data.importance_score === "number"
          ? data.importance_score
          : 1.0,
      originator_id: (data.originator_id as string) || undefined,
      originator_name: (data.originator_name as string) || undefined,
      destination: (data.destination as string) || undefined,
      status: (data.status as string) || undefined,
      assigned_to: (data.assigned_to as string) || undefined,
      due_at:
        typeof data.due_at === "number" ? data.due_at : undefined,
      last_checkin:
        typeof data.last_checkin === "number" ? data.last_checkin : undefined,
    };
  }

  // ── Conversation Tagging ────────────────────────────────────────────────────

  private generateTagLabel(content: string): string {
    const words = content
      .toLowerCase()
      .replace(/[^\w\s]/g, " ")
      .split(/\s+/)
      .filter((w) => w.length > 3)
      .slice(0, 4);
    return words.length > 0 ? words.join(" ") : content.slice(0, 40).trim();
  }

  private getTagNode(
    tagId: string,
  ): (ConversationTag & { _node: Record<string, unknown> }) | null {
    const data = this.napiGet(CONV_TAG + tagId);
    if (!data) return null;
    return {
      id: tagId,
      label: (data.label as string) ?? "",
      embedding: toNumberArray(data.embedding),
      parent_tag_id:
        (data.parent_tag_id as string | undefined) ?? undefined,
      message_ids: Array.isArray(data.message_ids)
        ? (data.message_ids as string[])
        : [],
      created_at: (data.created_at as number) ?? 0,
      updated_at: (data.updated_at as number) ?? 0,
      similarity_threshold:
        typeof data.similarity_threshold === "number"
          ? data.similarity_threshold
          : 0.85,
      _node: data,
    };
  }

  private putTagNode(tag: ConversationTag): void {
    this.napiPut(CONV_TAG + tag.id, {
      id: tag.id,
      label: tag.label,
      embedding: tag.embedding,
      parent_tag_id: tag.parent_tag_id ?? null,
      message_ids: tag.message_ids,
      created_at: tag.created_at,
      updated_at: tag.updated_at,
      similarity_threshold: tag.similarity_threshold,
    });
  }

  private addMemoryToTag(
    tagId: string,
    memoryId: string,
    newEmbedding: number[],
  ): void {
    const tag = this.getTagNode(tagId);
    if (!tag) return;
    if (tag.message_ids.includes(memoryId)) return;

    const messageIds = [...tag.message_ids, memoryId];
    const count = messageIds.length;
    const updatedEmbedding = tag.embedding.map(
      (v, i) => (v * (count - 1) + (newEmbedding[i] ?? 0)) / count,
    );

    this.putTagNode({
      ...tag,
      embedding: updatedEmbedding,
      message_ids: messageIds,
      updated_at: Date.now(),
    });
  }

  private async assignConversationTag(
    memoryId: string,
    embedding: number[],
    content: string,
    similarityThreshold = 0.85,
    parentThreshold = 0.7,
  ): Promise<string[]> {
    const all = this.napiList();
    const tagNodes = all.filter((n) => n.id.startsWith(CONV_TAG));

    let bestMatchId: string | null = null;
    let bestMatchSim = -1;
    let potentialParentId: string | null = null;
    let potentialParentSim = -1;

    for (const node of tagNodes) {
      const tagId = node.id.slice(CONV_TAG.length);
      const tagEmbedding = toNumberArray(node.data.embedding);
      if (tagEmbedding.length === 0) continue;
      const sim = cosineSimilarity(embedding, tagEmbedding);
      const threshold =
        typeof node.data.similarity_threshold === "number"
          ? node.data.similarity_threshold
          : similarityThreshold;

      if (sim >= threshold && sim > bestMatchSim) {
        bestMatchSim = sim;
        bestMatchId = tagId;
      } else if (
        sim >= parentThreshold &&
        sim > potentialParentSim
      ) {
        potentialParentSim = sim;
        potentialParentId = tagId;
      }
    }

    if (bestMatchId) {
      this.addMemoryToTag(bestMatchId, memoryId, embedding);
      return [bestMatchId];
    }

    const newTagId = randomUUID();
    const now = Date.now();
    this.putTagNode({
      id: newTagId,
      label: this.generateTagLabel(content),
      embedding,
      parent_tag_id: potentialParentId ?? undefined,
      message_ids: [memoryId],
      created_at: now,
      updated_at: now,
      similarity_threshold: similarityThreshold,
    });

    return [newTagId];
  }

  async getConversationTags(): Promise<ConversationTag[]> {
    this.ensureOpen();
    const all = this.napiList();
    const tags: ConversationTag[] = [];

    for (const node of all) {
      if (!node.id.startsWith(CONV_TAG)) continue;
      const tagId = node.id.slice(CONV_TAG.length);
      const d = node.data;
      tags.push({
        id: tagId,
        label: (d.label as string) ?? "",
        embedding: toNumberArray(d.embedding),
        parent_tag_id: (d.parent_tag_id as string | undefined) ?? undefined,
        message_ids: Array.isArray(d.message_ids)
          ? (d.message_ids as string[])
          : [],
        created_at: (d.created_at as number) ?? 0,
        updated_at: (d.updated_at as number) ?? 0,
        similarity_threshold:
          typeof d.similarity_threshold === "number"
            ? d.similarity_threshold
            : 0.85,
      });
    }

    return tags.sort((a, b) => b.updated_at - a.updated_at);
  }

  async getMessagesForTag(tagId: string): Promise<MemoryEntry[]> {
    this.ensureOpen();
    const tag = this.getTagNode(tagId);
    if (!tag || tag.message_ids.length === 0) return [];

    const entries: MemoryEntry[] = [];
    for (const memId of tag.message_ids) {
      const data = this.napiGet(MEM + memId);
      if (data) entries.push(this.nodeToEntry(data, memId));
    }

    return entries.sort((a, b) => a.created_at - b.created_at);
  }

  async getRelatedTags(tagId: string): Promise<ConversationTag[]> {
    this.ensureOpen();
    const tag = this.getTagNode(tagId);
    if (!tag) return [];

    const all = this.napiList();
    const related = new Map<string, ConversationTag>();

    const addNode = (node: NapiListItem) => {
      const id = node.id.slice(CONV_TAG.length);
      if (id === tagId) return;
      const d = node.data;
      related.set(id, {
        id,
        label: (d.label as string) ?? "",
        embedding: toNumberArray(d.embedding),
        parent_tag_id: (d.parent_tag_id as string | undefined) ?? undefined,
        message_ids: Array.isArray(d.message_ids)
          ? (d.message_ids as string[])
          : [],
        created_at: (d.created_at as number) ?? 0,
        updated_at: (d.updated_at as number) ?? 0,
        similarity_threshold:
          typeof d.similarity_threshold === "number"
            ? d.similarity_threshold
            : 0.85,
      });
    };

    for (const node of all) {
      if (!node.id.startsWith(CONV_TAG)) continue;
      const d = node.data;
      const id = node.id.slice(CONV_TAG.length);

      if (d.parent_tag_id === tagId) {
        addNode(node);
        continue;
      }

      if (tag.parent_tag_id) {
        if (id === tag.parent_tag_id) {
          addNode(node);
          continue;
        }
        if (d.parent_tag_id === tag.parent_tag_id) {
          addNode(node);
        }
      }
    }

    return Array.from(related.values());
  }
}

// ── Factory helper ────────────────────────────────────────────────────────────

/**
 * Check whether the PluresDB NAPI module with embeddings support is available.
 *
 * Returns true when:
 * 1. @plures/pluresdb is installed
 * 2. The native binary loader exists (crates/pluresdb-node/index.js)
 *
 * Note: this does NOT verify whether --features embeddings was enabled at
 * compile time.  That check happens at runtime in PluresNapiBackend.open().
 */
export async function isNapiBackendAvailable(): Promise<boolean> {
  try {
    const { createRequire } = await import("node:module");
    const { existsSync } = await import("node:fs");
    const { dirname, join } = await import("node:path");
    const require = createRequire(import.meta.url);
    const napiIndex = require.resolve("@plures/pluresdb");
    const nativeLoader = join(
      dirname(napiIndex),
      "../../crates/pluresdb-node/index.js",
    );
    return existsSync(nativeLoader);
  } catch {
    return false;
  }
}
